#!/usr/bin/env python3
"""
EDGE Smart Video — Professional Video Slideshow
Text-first, branded video slideshow with real content generated by LLM.
No reliance on unreliable AI image APIs.

Usage:
  python3 compose_video.py --slides ./output/slides.json --output-dir ./output

  --slides JSON file with an array of slide objects:
    [
      {"type": "title|content|cta", "headline": "...", "bullets": ["..."], "subtitle": "..."}
    ]
"""

import json
import os
import sys
import html as html_mod


BRAND = {
    "bg": "#f0f4f0",         # Light green-gray background
    "surface": "#ffffff",     # White card surface
    "primary": "#1a7a3a",     # Professional deep green
    "primary_dim": "#145c2d", # Darker green for gradients
    "text": "#1e293b",        # Slate-800 near-black text
    "text_dim": "#64748b",    # Slate-500 medium gray
    "accent": "#d97706",      # Amber-600 accent for CTA contrast
    "font": "'Inter', 'Helvetica Neue', Arial, sans-serif"
}


def build_video_html(topic, sector, slides, output_dir, background_image=None, schematics=None):
    """Create a professional auto-advancing video-style slideshow."""
    slides_data = json.dumps(slides)
    schematics_data = json.dumps(schematics) if schematics else "[]"
    bg_style = ""
    if background_image and os.path.exists(background_image):
        import base64
        with open(background_image, "rb") as f:
            img = base64.b64encode(f.read()).decode()
        bg_style = f"""
        body::before {{
            content: '';
            position: fixed;
            inset: 0;
            background: url('data:image/jpeg;base64,{img}') center/cover no-repeat;
            opacity: 0.08;
            z-index: 0;
        }}
        """

    html_content = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>EDGE | {html_mod.escape(topic)}</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800&display=swap" rel="stylesheet">
<style>
* {{ margin: 0; padding: 0; box-sizing: border-box; }}
body {{
    background: {BRAND['bg']};
    font-family: {BRAND['font']};
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    overflow: hidden;
}}
{bg_style}
.player {{
    width: 100%;
    max-width: 960px;
    aspect-ratio: 16/9;
    background: {BRAND['surface']};
    position: relative;
    overflow: hidden;
    border-radius: 16px;
    box-shadow:
        0 0 0 1px rgba(26, 122, 58, 0.1),
        0 30px 80px rgba(0, 0, 0, 0.6);
    z-index: 1;
}}

/* Progress bar */
.progress-bar {{
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: rgba(0,0,0,0.04);
    z-index: 100;
}}
.progress-fill {{
    height: 100%;
    background: linear-gradient(90deg, {BRAND['primary']}, {BRAND['primary_dim']});
    transition: width 0.1s linear;
    width: 0%;
}}

/* Slides */
.slide {{
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    opacity: 0;
    transition: opacity 0.6s ease, transform 0.6s ease;
    transform: scale(0.97);
    padding: 60px 80px;
}}
.slide.active {{
    opacity: 1;
    transform: scale(1);
}}

/* Brand watermark */
.brand-watermark {{
    position: absolute;
    top: 24px;
    left: 32px;
    z-index: 50;
    display: flex;
    align-items: center;
    gap: 10px;
}}
.brand-dot {{
    width: 8px; height: 8px;
    border-radius: 50%;
    background: {BRAND['primary']};
}}
.brand-name {{
    color: {BRAND['primary']};
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 3px;
    text-transform: uppercase;
    opacity: 0.6;
}}

/* Title slide */
.slide-title {{
    justify-content: center;
    align-items: center;
    text-align: center;
}}
.slide-title .sector-tag {{
    color: {BRAND['primary']};
    font-size: clamp(12px, 1.4vw, 18px);
    font-weight: 600;
    letter-spacing: 6px;
    text-transform: uppercase;
    margin-bottom: 24px;
    opacity: 0;
    animation: fadeUp 0.6s 0.2s forwards;
}}
.slide-title h1 {{
    color: {BRAND['text']};
    font-size: clamp(28px, 4vw, 56px);
    font-weight: 800;
    line-height: 1.15;
    max-width: 800px;
    margin: 0 auto 20px;
    opacity: 0;
    animation: fadeUp 0.6s 0.4s forwards;
}}
.slide-title .subtitle {{
    color: {BRAND['text_dim']};
    font-size: clamp(14px, 1.5vw, 22px);
    font-weight: 300;
    opacity: 0;
    animation: fadeUp 0.6s 0.6s forwards;
}}
.slide-title .tagline-bar {{
    margin-top: 32px;
    width: 60px;
    height: 2px;
    background: {BRAND['primary']};

